from collections import defaultdict
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import os
from pathlib import Path
import socket
from threading import Lock


def capture_rows(path):
    with path.open(encoding="utf-8") as capture:
        for line in capture:
            try:
                yield json.loads(line)
            except ValueError:
                yield {}


def key(method, path, body):
    return method, path, json.dumps(body, sort_keys=True, separators=(",", ":"))


def serve(path):
    queue = defaultdict(list)
    cursors = defaultdict(int)
    consumed = []
    lock = Lock()
    for index, row in enumerate(capture_rows(path)):
        if "response" in row or ("status" in row and row["status"] is None):
            records = queue[key(row["method"], row["path"], row["request"])]
            body = row.get("response")
            if records and row["method"] == "GET" and isinstance(body, dict):
                previous = records[-1][1].get("response")
                run_state = body.get("status")
                if (row["status"] == records[-1][1]["status"] == 200
                        and run_state in {"queued", "running", "in_progress"}
                        and isinstance(previous, dict) and previous.get("status") == run_state):
                    continue
            records.append((index, row))

    class Handler(BaseHTTPRequestHandler):
        protocol_version = "HTTP/1.1"

        def log_message(self, *_):
            pass

        def reply(self, status, body):
            payload = json.dumps(body, ensure_ascii=False).encode()
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(payload)))
            self.end_headers()
            self.wfile.write(payload)

        def handle_request(self):
            if self.path == "/_replay/health":
                self.reply(200, {"status": "ok"})
                return
            if self.path == "/_replay/served":
                with lock:
                    items = list(consumed)
                self.reply(200, {"indexes": items})
                return
            data = self.rfile.read(int(self.headers.get("Content-Length", "0")))
            body = json.loads(data) if data else ""
            signature = key(self.command, self.path, body)
            with lock:
                records = queue.get(signature, ())
                if records:
                    index, row = records[min(cursors[signature], len(records) - 1)]
                    cursors[signature] += 1
                    consumed.append(index)
                else:
                    row = {}
            if not row:
                self.reply(404, {"error": "Request not present in offline capture"})
            elif row["status"] is None:
                self.close_connection = True
                self.connection.shutdown(socket.SHUT_RDWR)
            else:
                self.reply(row["status"], row["response"])

        do_GET = do_POST = do_DELETE = handle_request

    ThreadingHTTPServer(("0.0.0.0", 8080), Handler).serve_forever()


if __name__ == "__main__":
    serve(Path(os.environ.get("REPLAY_CAPTURE", "/capture/provider.jsonl")))
